static void applyMigrations(Connection conn, String[] migrations) throws SQLException {
  for (int i = 0; i < migrations.length; i++) {
    if (!isMigrationApplied(conn, i)) {
      try (Statement s = conn.createStatement()) { s.execute(migrations[i]); }
      recordMigration(conn, i);
    }
  }
}

static void dropTableSafely(Connection conn, String tableName, boolean confirmed) throws SQLException {
  if (!confirmed) throw new IllegalStateException("Usuniecie tabeli wymaga potwierdzenia");
  try (Statement s = conn.createStatement()) { s.execute("DROP TABLE " + tableName); }
}

