static void teardownSchemaInCorrectOrder(Connection conn, String... tableNames) throws SQLException {
  for (String name : tableNames) dropTableIfExists(conn, name);
}
teardownSchemaInCorrectOrder(conn, "reviews", "books", "authors");

class SchemaBootstrapper {
  void bootstrap(Connection conn) throws SQLException {
    createTableIfNotExists(conn, "authors", "(id INT PRIMARY KEY)");
    createTableIfNotExists(conn, "books", "(id INT PRIMARY KEY, author_id INT REFERENCES authors(id))");
    createTableIfNotExists(conn, "reviews", "(id INT PRIMARY KEY, book_id INT REFERENCES books(id))");
  }
  void smokeTest(Connection conn) throws SQLException { /* wstaw i odczytaj po 1 wierszu w kazdej tabeli */ }
  void teardown(Connection conn) throws SQLException { teardownSchemaInCorrectOrder(conn, "reviews", "books", "authors"); }
}
